import type { Metadata, Viewport } from "next";
import { preload } from "react-dom";
import { Toaster } from "sonner";
import { FeedbackButton } from "@/components/feedback-button";
import { OrganizationLd, WebsiteLd } from "@/lib/seo/jsonld";
import {
  SITE_NAME,
  SITE_TAGLINE,
  SITE_TWITTER,
  SITE_URL,
} from "@/lib/seo/metadata";
import "./globals.css";
import "./fonts.css";

// Self-hosted font subsets generated by scripts/fonts/subset.py (see
// scripts/fonts/README.md). Only the small core files are preloaded; the
// extended files sit behind unicode-range and load only on pages that need them.
const FONT_PRELOADS = [
  "/fonts/space-grotesk-core.fe7a1cc6.woff2",
  "/fonts/inter-core.62253817.woff2",
  "/fonts/dm-mono-400-core.61ca72dc.woff2",
  "/fonts/dm-mono-500-core.6fc92fec.woff2",
];

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#0A1628",
  colorScheme: "dark",
};

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: {
    default: `${SITE_NAME}: Free, Open-Source Draft Randomizer`,
    template: `%s | ${SITE_NAME}`,
  },
  description: SITE_TAGLINE,
  applicationName: SITE_NAME,
  icons: {
    other: [{ rel: "mask-icon", url: "/safari-pinned-tab.svg", color: "#00E676" }],
  },
  authors: [{ name: SITE_NAME, url: SITE_URL }],
  generator: "Next.js",
  referrer: "origin-when-cross-origin",
  creator: SITE_NAME,
  publisher: SITE_NAME,
  formatDetection: { email: false, address: false, telephone: false },
  alternates: {
    canonical: "/",
    // Points AI crawlers at the curated Markdown site map served by
    // app/llms.txt/route.ts.
    types: {
      "text/plain": [{ url: "/llms.txt", title: `${SITE_NAME} llms.txt` }],
    },
  },
  openGraph: {
    type: "website",
    siteName: SITE_NAME,
    locale: "en_US",
    url: SITE_URL,
    title: `${SITE_NAME}: Free, Open-Source Draft Randomizer`,
    description: SITE_TAGLINE,
    images: [
      {
        url: "/opengraph-image",
        width: 1200,
        height: 630,
        alt: `${SITE_NAME}: transparent, verifiable draft randomizer`,
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    title: `${SITE_NAME}: Free, Open-Source Draft Randomizer`,
    description: SITE_TAGLINE,
    images: ["/opengraph-image"],
    site: SITE_TWITTER,
    creator: SITE_TWITTER,
  },
  robots: {
    index: true,
    follow: true,
    googleBot: {
      index: true,
      follow: true,
      "max-image-preview": "large",
      "max-snippet": -1,
      "max-video-preview": -1,
    },
  },
  category: "sports",
  verification: {
    google: process.env.NEXT_PUBLIC_GOOGLE_SITE_VERIFICATION,
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  for (const href of FONT_PRELOADS) {
    preload(href, { as: "font", type: "font/woff2", crossOrigin: "anonymous" });
  }
  return (
    <html
      lang="en"
      className="fonts h-full antialiased"
    >
      <body className="bg-midnight text-chalk relative flex min-h-full flex-col">
        <div className="relative z-10 flex min-h-full flex-col">{children}</div>
        <FeedbackButton />
        <Toaster
          theme="dark"
          richColors
          toastOptions={{
            style: {
              background: "var(--color-sideline)",
              color: "var(--color-chalk)",
              border: "1px solid rgba(100, 116, 139, 0.3)",
            },
          }}
        />
        {/*
          Analytics is Cloudflare Web Analytics, enabled on the zone by the
          Pulumi program in program/. The zone is proxied, so Cloudflare
          injects the beacon at the edge — there is deliberately no script tag
          or npm package here. Dashboard: Analytics & Logs -> Web Analytics.
        */}
        <OrganizationLd />
        <WebsiteLd />
      </body>
    </html>
  );
}
